css:
.pv[data-theme=dark]{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--bg:#0A0A0A;--bg2:#111;--muted:#171717;--line:#262626;--line2:#404040;--solid:#F5F5F5;--on:#0A0A0A;
 --ok:#93CFA6;--ok-bg:#0F2A19;--err:#FFA19C;--err-bd:#F97066;--err-bg:#3A1210;--focus:#F5F5F5;--scrim:rgba(0,0,0,.6)}
.i{flex:none;display:block}
button{font:inherit;color:inherit}
.bt{height:32px;padding:0 12px;border:1px solid var(--line2);border-radius:8px;background:var(--bg);display:inline-flex;align-items:center;gap:6px;font:600 13px/18px Inter;white-space:nowrap;cursor:pointer}
.bt.sm{height:28px;padding:0 8px;font-size:12.5px}
.bt.big{height:48px;justify-content:center;border-radius:12px;font-size:14px}
.bt[disabled]{opacity:.5;cursor:not-allowed}
.ib{width:32px;height:32px;border:0;background:none;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;color:var(--fg3);cursor:pointer;flex:none}
.fu{display:flex;flex-direction:column;gap:6px;min-width:0;position:relative}
.lb{font:500 14px/20px Inter;color:var(--fg2);display:flex;gap:4px}
.lbi{font:500 12px/16px Inter;color:var(--fg3);display:flex;gap:4px;margin-bottom:2px}
.req{color:var(--err)}
.hn{font-size:12.5px;line-height:18px;color:var(--fg3)}
.fe{font-size:12.5px;line-height:18px;color:var(--err);display:flex;gap:6px;align-items:center}
.dz{border:1px solid var(--line2);border-radius:12px;background:var(--bg);cursor:pointer}
.pv[data-D8=b] .dz,.pv[data-D8=b] .az{border-style:dashed;border-color:var(--fg3)}
.dz-a{padding:16px 24px;display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center}
.dz-b{padding:12px 12px 12px 14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.dz-m{flex:1;min-width:150px}
.dz-c{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.dz-t{font-size:13.5px;line-height:20px;color:var(--fg3)}
.dz-t b{color:var(--fg);font-weight:600}
.dz-t .lk{text-decoration:underline;text-underline-offset:2px}
.dz-h{font-size:12px;line-height:18px;color:var(--fg3)}
.fi{width:40px;height:40px;border-radius:10px;border:1px solid var(--line);display:inline-flex;align-items:center;justify-content:center;color:var(--fg2);background:var(--bg);flex:none;margin-bottom:8px}
.dz-b .fi,.fi.sm{width:36px;height:36px;margin:0}
.dz.hover{border:2px solid var(--focus);background:var(--bg2)}
.pv[data-D8=b] .dz.hover{border-style:dashed;border-color:var(--focus)}
.dz.hover .fi{color:var(--fg)}
.dz.disabled,.az.disabled{background:var(--muted);cursor:not-allowed;opacity:.6}
.dz.error,.az.error,.az2.error .bt{border-color:var(--err-bd)}
.dz-c.disabled .bt{opacity:.5}
.fl{display:flex;flex-direction:column;gap:8px}
.fr{position:relative;display:flex;gap:12px;align-items:flex-start;padding:12px 8px 12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--bg);overflow:hidden;min-width:0}
.fr.error{border-color:var(--err-bd)}
.fr .fill{position:absolute;left:0;top:0;bottom:0;background:var(--muted);z-index:0}
.fr>*{position:relative}
.ft{flex:none;display:block}
.th{width:40px;height:40px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#5b6575;flex:none}
.fm{flex:1;min-width:0}
.fn{font:500 13.5px/20px Inter;color:var(--fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fs{display:flex;align-items:center;gap:8px;font-size:12.5px;line-height:18px;color:var(--fg3);margin-top:1px;flex-wrap:wrap}
.sep{width:1px;height:12px;background:var(--line2)}
.st{display:inline-flex;align-items:center;gap:4px;font-weight:500}
.st.ok{color:var(--ok)}
.st.er{color:var(--err)}
.bar{height:6px;border-radius:99px;background:var(--muted);margin-top:8px;overflow:hidden}
.bar i{display:block;height:100%;background:var(--solid);border-radius:99px}
.lkr{border:0;background:none;padding:0;margin-top:6px;font:600 13px/18px Inter;color:var(--err);cursor:pointer}
.fa{display:flex;gap:4px;align-items:center;align-self:center}
.del{align-self:flex-start;margin-top:-6px;margin-right:-2px}
.fu.m .lb{font-size:13px}
.az{border:1px solid var(--line2);border-radius:16px;padding:14px;display:flex;gap:12px;align-items:center;background:var(--bg)}
.az .fi{margin:0;border-radius:50%;width:44px;height:44px;background:var(--muted);border:0}
.az-m{flex:1;min-width:0}
.az2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.gr{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.tl{position:relative;aspect-ratio:1;border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.tl .ph{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#5b6575}
.tl.add{border:1px dashed var(--fg3);background:var(--bg);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font:500 11.5px Inter;color:var(--fg2);cursor:pointer}
.tl.error{border:2px solid var(--err-bd)}
.tov{position:absolute;inset:0;background:rgba(10,10,10,.45);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font:600 12px Inter}
.tov.er{background:rgba(180,35,24,.55)}
.ring{width:24px;height:24px;border-radius:50%;background:conic-gradient(#fff calc(var(--p)*1%),rgba(255,255,255,.3) 0)}
.tcap{position:absolute;left:6px;bottom:6px;right:6px;font:600 10.5px/14px Inter;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.6);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tx{position:absolute;top:5px;right:5px;width:22px;height:22px;border-radius:50%;border:0;background:rgba(10,10,10,.55);color:#fff;display:flex;align-items:center;justify-content:center}
.scr{position:absolute;inset:0;background:var(--scrim);z-index:8;border-radius:inherit}
.sht{position:absolute;left:0;right:0;bottom:0;z-index:9;background:var(--bg);border-radius:28px 28px 0 0;padding:8px 16px 24px;display:flex;flex-direction:column}
.sht .hd{width:36px;height:4px;border-radius:2px;background:var(--line2);align-self:center;margin-bottom:12px}
.sh-t{font:600 17px/24px Inter;margin-bottom:6px}
.sh-i{height:52px;display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--line);font:500 15px Inter}
.pvm:not([data-D1="a"]) [data-mshow~="D1:a"],.pvm:not([data-D1="b"]) [data-mshow~="D1:b"],.pvm:not([data-D2="a"]) [data-mshow~="D2:a"],.pvm:not([data-D2="b"]) [data-mshow~="D2:b"],.pvm:not([data-D2="c"]) [data-mshow~="D2:c"],.pvm:not([data-D3="a"]) [data-mshow~="D3:a"],.pvm:not([data-D3="b"]) [data-mshow~="D3:b"],.pvm:not([data-D4="a"]) [data-mshow~="D4:a"],.pvm:not([data-D4="b"]) [data-mshow~="D4:b"],.pvm:not([data-D5="a"]) [data-mshow~="D5:a"],.pvm:not([data-D5="b"]) [data-mshow~="D5:b"],.pvm:not([data-D6="a"]) [data-mshow~="D6:a"],.pvm:not([data-D6="b"]) [data-mshow~="D6:b"],.pvm:not([data-D6="c"]) [data-mshow~="D6:c"],.pvm:not([data-D7="a"]) [data-mshow~="D7:a"],.pvm:not([data-D7="b"]) [data-mshow~="D7:b"],.pvm:not([data-D8="a"]) [data-mshow~="D8:a"],.pvm:not([data-D8="b"]) [data-mshow~="D8:b"]{display:none!important}
.pv[data-theme=dark] .pv{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--bg:#0A0A0A;--bg2:#111;--muted:#171717;--line:#262626;--line2:#404040;--solid:#F5F5F5;--on:#0A0A0A;
 --ok:#93CFA6;--ok-bg:#0F2A19;--err:#FFA19C;--err-bd:#F97066;--err-bg:#3A1210;--focus:#F5F5F5;--scrim:rgba(0,0,0,.6)}
.dz.focus,.bt.focus,.ib.focus,.az.focus,.lkr.focus{outline:2px solid var(--focus);outline-offset:2px}
.ib.hv{background:var(--muted);color:var(--fg)}
.dz.hv{border-color:var(--fg3);background:var(--bg2)}
.bt.hv{background:var(--muted)}
.pv[data-platform=mobile] .fr{padding:12px 4px 12px 12px;border-radius:14px}
.pv[data-platform=mobile] .fr .ib{width:40px;height:40px}
.pv[data-platform=mobile] .fn{font-size:14px}
.lb{display:block}
.req{margin-left:3px}
.fe{align-items:flex-start}
.fe .i{margin-top:2px}
.dz-c.hv .bt{background:var(--muted)}
.dz-c.focus .bt{outline:2px solid var(--focus);outline-offset:2px}
.dz-c.error .bt{border-color:var(--err-bd)}
.st.up{color:var(--fg3)}
.az{min-height:72px;box-sizing:border-box}

cssScreen:
.pv{position:relative;--fg:#171717;--fg2:#525252;--fg3:#737373;--bg:#fff;--bg2:#FAFAFA;--muted:#F5F5F5;--line:#E5E5E5;--line2:#D4D4D4;--solid:#171717;--on:#fff;
 --ok:#1B7542;--ok-bg:#E8F5EC;--err:#B42318;--err-bd:#F04438;--err-bg:#FDECEC;--focus:#171717;--scrim:rgba(10,10,10,.45);
 color:var(--fg);font:14px/20px Inter,system-ui,sans-serif}
.bt.pri{background:var(--solid);color:var(--on);border-color:var(--solid)}
.pad{padding:16px 24px 24px;display:flex;flex-direction:column;gap:16px}
.mpad{padding:12px 16px 96px;display:flex;flex-direction:column;gap:16px}
table{width:100%;border-collapse:collapse}
td,th{padding:11px 16px;border-bottom:1px solid var(--line);text-align:left;font-size:13px}
th{color:var(--fg3);font-weight:500;background:var(--muted)}
.tb{border:1px solid var(--line);border-radius:12px;overflow:hidden}
.chip{display:inline-block;font:500 12px/18px Inter;padding:2px 8px;border-radius:999px;background:var(--muted)}
.mw{position:absolute;inset:0;background:var(--scrim);display:flex;align-items:flex-start;justify-content:center;padding-top:56px;z-index:6}
.md{width:560px;background:var(--bg);border-radius:16px;box-shadow:0 20px 40px rgba(0,0,0,.2);display:flex;flex-direction:column}
.md-h{padding:20px 24px 8px;display:flex;gap:12px;align-items:flex-start}
.md-h b{font:600 18px/28px Inter;display:block}
.md-h span{color:var(--fg3);font-size:13.5px}
.md-b{padding:12px 24px 8px;display:flex;flex-direction:column;gap:16px}
.md-f{padding:16px 24px 20px;display:flex;justify-content:flex-end;gap:8px}
.inp{height:32px;border:1px solid var(--line2);border-radius:8px;padding:0 10px;display:flex;align-items:center;color:var(--fg3);font-size:13.5px}
.ta{height:64px;align-items:flex-start;padding-top:6px}
.card{border:1px solid var(--line);border-radius:12px;padding:16px 20px;display:flex;flex-direction:column;gap:16px}
.card .h{font:600 15px/22px Inter;display:flex;justify-content:space-between;align-items:center}
.cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}
dl{display:grid;grid-template-columns:130px 1fr;gap:6px 12px;margin:0;font-size:13px}
dt{color:var(--fg3)}
dd{margin:0}
.mcard{border:1px solid var(--line);border-radius:16px;padding:12px 14px;display:flex;flex-direction:column;gap:2px}
.mcard b{font-size:15px}
.mcard span{color:var(--fg3);font-size:13px}
.pt{display:flex;gap:8px;align-items:center;font:600 14px Inter}
.pt .chip{margin-left:auto;font-weight:500}
.cta{position:sticky;bottom:0;height:52px;border:0;border-radius:999px;background:var(--solid);color:var(--on);font:600 16px Inter;width:100%}
.pv[data-platform=mobile] .cols{grid-template-columns:1fr}
.mf .fu{position:static}
.mf{box-sizing:border-box;position:relative;width:351px;min-height:300px;padding:16px;display:flex;flex-direction:column;gap:16px;background:var(--bg);overflow:hidden}
.mf.tall{min-height:520px}
.gl{font:600 12px/16px Inter;color:var(--fg3);text-transform:uppercase;letter-spacing:.04em}
.sh0{background:#C9D4E0}.sh1{background:#D8CFC2}.sh2{background:#C4D1C8}.sh3{background:#D3C9D8}
